import { useEffect, useMemo, useState } from 'react';
import type { LucideIcon } from 'lucide-react';
import {
  AlertTriangle, ArrowLeft, BellRing, Bot, Building2, CalendarClock, Check, CheckCircle2, ChevronRight,
  CircleDollarSign, ClipboardCheck, Clock3, FileCheck2, FilePenLine, FileSearch, FileText, GitBranch,
  Inbox, Layers3, Loader2, Plus, Save, Search, Send, ShieldCheck, Sparkles, Upload, UserRoundCheck, XCircle,
} from 'lucide-react';
import { toast } from 'sonner';
import { useLocation, useSearchParams } from 'react-router-dom';
import { useContracts } from '../context/ContractContext';
import { ContractPayments } from '../components/ContractPayments';
import { ContractReviewWorkspace } from '../components/ContractReviewWorkspace';
import { ContractCloseout } from '../components/ContractCloseout';
import { ContractKnowledgeSearch } from '../components/ContractKnowledgeSearch';
import { CorporateStructureChart } from '../components/CorporateStructureChart';
import { useVendors } from '../context/VendorContext';
import { useAuth } from '../context/AuthContext';
import { DraftHistory, ManualClauseForm, NewObligationForm, ObligationChainCard, SmartDocumentRepository, TemplateManager } from './ContractAdvanced';
import type {
  Contract, ContractClause, ContractObligation, ContractPlaybookRule, ContractRoleType, CorporateEntity, CorporateOwnershipInterest, CreateContractInput,
  CreateCorporateEntityInput, RoleAssignment,
} from '../contractTypes';

type View = 'workflow' | 'dashboard' | 'register' | 'smart-files' | 'drafting' | 'monitoring' | 'structure' | 'configuration';
type DetailTab = 'overview' | 'metadata' | 'clauses' | 'review' | 'obligations' | 'payments' | 'documents' | 'closeout' | 'approvals' | 'audit';
const fieldClass = 'w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100 disabled:bg-slate-50';
const labelClass = 'mb-1.5 block text-xs font-bold uppercase tracking-wide text-slate-500';
const clean = (value: string) => value.replace(/_/g, ' ').toLowerCase().replace(/\b\w/g, letter => letter.toUpperCase());
const displayDate = (value?: string) => value ? new Date(`${value.slice(0, 10)}T00:00:00`).toLocaleDateString('en-MY', { day: '2-digit', month: 'short', year: 'numeric' }) : '—';
const statusStyle: Record<string, string> = {
  ACTIVE: 'bg-emerald-50 text-emerald-700', READY_TO_ACTIVATE: 'bg-cyan-50 text-cyan-700', APPROVED: 'bg-green-50 text-green-700',
  COMPLETED: 'bg-green-50 text-green-700', CONFIRMED: 'bg-green-50 text-green-700', DUE_SOON: 'bg-amber-50 text-amber-700',
  OVERDUE: 'bg-red-50 text-red-700', REJECTED: 'bg-red-50 text-red-700', FAILED: 'bg-red-50 text-red-700',
  CLAUSE_REVIEW: 'bg-purple-50 text-purple-700', ENTITY_REVIEW: 'bg-purple-50 text-purple-700', REVIEW_REQUIRED: 'bg-purple-50 text-purple-700',
  AI_EXTRACTED: 'bg-blue-50 text-blue-700', PROCESSING: 'bg-blue-50 text-blue-700', QUEUED: 'bg-blue-50 text-blue-700',
  DRAFT: 'bg-slate-100 text-slate-700', LEGAL_REVIEW: 'bg-indigo-50 text-indigo-700', EXECUTED: 'bg-teal-50 text-teal-700',
};

function Badge({ value }: { value: string }) {
  return <span className={`inline-flex rounded-full px-2.5 py-1 text-[11px] font-bold ${statusStyle[value] || 'bg-slate-100 text-slate-700'}`}>{clean(value)}</span>;
}

function Card({ title, icon: Icon, children, action }: { title: string; icon?: LucideIcon; children: React.ReactNode; action?: React.ReactNode }) {
  return <section className="rounded-2xl border border-slate-100 bg-white p-5 shadow-sm">
    <div className="flex items-center justify-between gap-3"><div className="flex items-center gap-2 font-bold text-blue-950">{Icon && <Icon className="h-5 w-5 text-blue-700" />}{title}</div>{action}</div>
    <div className="mt-4">{children}</div>
  </section>;
}

function JobProgress({ contractId }: { contractId: string }) {
  const { jobs } = useContracts();
  const job = jobs.find(item => item.contractId === contractId && !['COMPLETED', 'PARTIAL', 'FAILED'].includes(item.stage));
  if (!job) return null;
  return <div className="rounded-xl border border-blue-100 bg-blue-50 p-4">
    <div className="flex justify-between text-sm font-bold text-blue-900"><span>{clean(job.stage)}</span><span>{job.progress}%</span></div>
    <div className="mt-2 h-2 overflow-hidden rounded-full bg-blue-100"><div className="h-full rounded-full bg-blue-700 transition-all" style={{ width: `${job.progress}%` }} /></div>
    <div className="mt-2 text-xs text-blue-700">{job.message}</div>
  </div>;
}

function Stat({ label, value, note, icon: Icon, tone = 'blue' }: { label: string; value: number; note: string; icon: LucideIcon; tone?: 'blue' | 'amber' | 'red' | 'green' }) {
  const colors = { blue: 'bg-blue-50 text-blue-700', amber: 'bg-amber-50 text-amber-700', red: 'bg-red-50 text-red-700', green: 'bg-emerald-50 text-emerald-700' };
  return <div className="rounded-2xl border border-slate-100 bg-white p-5 shadow-sm"><div className="flex items-start justify-between"><div><div className="text-xs font-bold uppercase tracking-widest text-slate-400">{label}</div><div className="mt-2 text-3xl font-black text-blue-950">{value}</div></div><div className={`rounded-xl p-2.5 ${colors[tone]}`}><Icon className="h-5 w-5" /></div></div><div className="mt-3 text-xs text-slate-500">{note}</div></div>;
}

function Dashboard({ openContract, changeView }: { openContract: (id: string) => void; changeView: (view: View) => void }) {
  const { dashboard, contracts, entities } = useContracts();
  const stages = [
    ['Request intake', 'Structured business need and entity'], ['Template drafting', 'Approved clauses and AI assistance'],
    ['Legal review', 'Redlines and controlled versions'], ['Approval routing', 'Value and authority matrix'],
    ['Smart repository', 'Signed file and contract intelligence'], ['Monitoring', 'Obligations, dates and alerts'],
  ];
  if (!dashboard) return <div className="py-20 text-center"><Loader2 className="mx-auto h-7 w-7 animate-spin text-blue-700" /></div>;
  return <div className="space-y-6">
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5">
      <Stat label="Active contracts" value={dashboard.activeContracts} note={`${dashboard.totalContracts} total records`} icon={FileCheck2} tone="green" />
      <Stat label="Renewal decisions" value={dashboard.renewalsDue} note="Notice deadline within 90 days" icon={CalendarClock} tone="amber" />
      <Stat label="Due soon" value={dashboard.obligationsDueSoon} note="Tracked contractual commitments" icon={Clock3} tone="blue" />
      <Stat label="Overdue" value={dashboard.overdueObligations} note="Immediate owner follow-up required" icon={AlertTriangle} tone="red" />
      <Stat label="Review issues" value={dashboard.openReviewIssues} note="Open playbook exceptions" icon={ShieldCheck} tone="amber" />
    </div>
    <Card title="End-to-end contract lifecycle" icon={GitBranch}>
      <div className="grid gap-2 lg:grid-cols-6">{stages.map(([title, note], index) => <div key={title} className="relative rounded-xl bg-slate-50 p-3"><div className="mb-3 flex h-8 w-8 items-center justify-center rounded-full bg-blue-800 text-xs font-black text-white">{index + 1}</div><div className="text-sm font-bold text-blue-950">{title}</div><div className="mt-1 text-xs leading-5 text-slate-500">{note}</div>{index < stages.length - 1 && <ChevronRight className="absolute -right-3 top-5 z-10 hidden h-5 w-5 text-blue-300 lg:block" />}</div>)}</div>
    </Card>
    <div className="grid gap-6 xl:grid-cols-[1.25fr_0.75fr]">
      <Card title="Upcoming commitments and renewal actions" icon={CalendarClock} action={<button onClick={() => changeView('monitoring')} className="text-xs font-bold text-blue-700">View all</button>}>
        <div className="space-y-2">{dashboard.upcoming.slice(0, 7).map(item => <button key={`${item.contractId}-${item.obligationId || item.title}`} onClick={() => openContract(item.contractId)} className="flex w-full items-center justify-between gap-4 rounded-xl border border-slate-100 p-3 text-left hover:border-blue-200 hover:bg-blue-50/30"><div className="min-w-0"><div className="truncate text-sm font-bold text-slate-900">{item.title}</div><div className="mt-1 truncate text-xs text-slate-500">{item.contractTitle} · {item.owner}</div></div><div className="shrink-0 text-right"><Badge value={item.status} /><div className="mt-1 text-xs text-slate-500">{displayDate(item.dueDate)}</div></div></button>)}{!dashboard.upcoming.length && <div className="rounded-xl border border-dashed p-8 text-center text-sm text-slate-500">No upcoming monitored actions.</div>}</div>
      </Card>
      <div className="space-y-6">
        <Card title="Corporate context" icon={Building2}><div className="text-3xl font-black text-blue-950">{entities.length}</div><div className="mt-1 text-sm text-slate-500">legal entities mapped in the group structure</div><button onClick={() => changeView('structure')} className="mt-4 w-full rounded-xl bg-blue-50 py-2.5 text-sm font-bold text-blue-800">Manage corporate structure</button></Card>
        <Card title="Recent contract activity" icon={Inbox}><div className="space-y-3">{contracts.slice().sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)).slice(0, 4).map(contract => <button key={contract.id} onClick={() => openContract(contract.id)} className="block w-full text-left"><div className="flex items-center justify-between gap-2"><span className="truncate text-sm font-bold">{contract.title}</span><Badge value={contract.status} /></div><div className="mt-1 text-xs text-slate-400">Updated {new Date(contract.updatedAt).toLocaleString()}</div></button>)}</div></Card>
      </div>
    </div>
  </div>;
}

const blankInput = (configuration?: { contractTypes: string[] } | null): CreateContractInput => ({
  title: '', contractType: configuration?.contractTypes[0] || 'Service Agreement', primaryEntityId: '', businessUnit: '', principalActivity: '', siteOrProject: '',
  counterpartyName: '', counterpartyRegistrationNumber: '', purpose: '', value: 0, currency: 'MYR', effectiveDate: '', expiryDate: '', noticePeriodDays: 60, autoRenewal: false, familyType: 'STANDALONE',
});

function ContractIntakeFields({ form, setForm, requireTemplate, hideEntity = false, documentFirst = false }: { form: CreateContractInput; setForm: (value: CreateContractInput) => void; requireTemplate?: boolean; hideEntity?: boolean; documentFirst?: boolean }) {
  const { entities, configuration, contracts } = useContracts();
  const { vendors } = useVendors();
  const entity = entities.find(item => item.id === form.primaryEntityId);
  return <div className="grid gap-4 md:grid-cols-2">
    <label><span className={labelClass}>Contract title {documentFirst ? '(optional)' : '*'}</span><input className={fieldClass} value={form.title} onChange={event => setForm({ ...form, title: event.target.value })} placeholder="e.g. Elevator maintenance agreement" /></label>
    <label><span className={labelClass}>Contract type</span><select className={fieldClass} value={form.contractType} onChange={event => setForm({ ...form, contractType: event.target.value })}>{configuration?.contractTypes.map(type => <option key={type}>{type}</option>)}</select></label>
    {!hideEntity && <label><span className={labelClass}>Contracting legal entity *</span><select className={fieldClass} value={form.primaryEntityId} onChange={event => setForm({ ...form, primaryEntityId: event.target.value, businessUnit: '', principalActivity: '', siteOrProject: '' })}><option value="">Select entity</option>{entities.filter(item => item.active).map(item => <option key={item.id} value={item.id}>{item.legalName}</option>)}</select></label>}
    <label><span className={labelClass}>Principal activity</span><select className={fieldClass} value={form.principalActivity} onChange={event => setForm({ ...form, principalActivity: event.target.value })}><option value="">Select activity</option>{entity?.principalActivities.map(item => <option key={item}>{item}</option>)}</select></label>
    <label><span className={labelClass}>Business unit</span><select className={fieldClass} value={form.businessUnit} onChange={event => setForm({ ...form, businessUnit: event.target.value })}><option value="">Select business unit</option>{entity?.businessUnits.map(item => <option key={item}>{item}</option>)}</select></label>
    <label><span className={labelClass}>Site / project</span><select className={fieldClass} value={form.siteOrProject} onChange={event => setForm({ ...form, siteOrProject: event.target.value })}><option value="">Not site-specific</option>{entity?.sites.map(item => <option key={item}>{item}</option>)}</select></label>
    <label><span className={labelClass}>Linked vendor (optional)</span><select className={fieldClass} value={form.vendorId || ''} onChange={event => { const vendor = vendors.find(item => item.id === event.target.value); setForm({ ...form, vendorId: vendor?.id, counterpartyName: vendor?.legalName || form.counterpartyName, counterpartyRegistrationNumber: vendor?.registrationNumber || form.counterpartyRegistrationNumber }); }}><option value="">Not linked to vendor register</option>{vendors.map(vendor => <option key={vendor.id} value={vendor.id}>{vendor.legalName} · {clean(vendor.onboardingStatus)}</option>)}</select></label>
    <label><span className={labelClass}>Counterparty {documentFirst ? '(optional)' : '*'}</span><input className={fieldClass} value={form.counterpartyName} onChange={event => setForm({ ...form, counterpartyName: event.target.value })} placeholder="Legal name" /></label>
    <label><span className={labelClass}>Counterparty registration</span><input className={fieldClass} value={form.counterpartyRegistrationNumber} onChange={event => setForm({ ...form, counterpartyRegistrationNumber: event.target.value })} /></label>
    <label className="md:col-span-2"><span className={labelClass}>Business purpose</span><textarea rows={2} className={fieldClass} value={form.purpose} onChange={event => setForm({ ...form, purpose: event.target.value })} placeholder="What is the contract for, and which outcome does it support?" /></label>
    <label><span className={labelClass}>Contract value</span><div className="flex"><select className="rounded-l-xl border border-r-0 border-slate-200 bg-slate-50 px-3 text-sm" value={form.currency} onChange={event => setForm({ ...form, currency: event.target.value })}><option>MYR</option><option>USD</option><option>SGD</option></select><input type="number" min="0" className={`${fieldClass} rounded-l-none`} value={form.value} onChange={event => setForm({ ...form, value: Number(event.target.value) })} /></div></label>
    <label><span className={labelClass}>Contract family</span><select className={fieldClass} value={form.familyType} onChange={event => setForm({ ...form, familyType: event.target.value as Contract['familyType'] })}><option value="STANDALONE">Standalone</option><option value="MASTER">Master agreement</option><option value="STATEMENT_OF_WORK">Statement of work</option><option value="AMENDMENT">Amendment</option><option value="RENEWAL">Renewal</option></select></label>
    {form.familyType !== 'STANDALONE' && form.familyType !== 'MASTER' && <label className="md:col-span-2"><span className={labelClass}>Parent / master contract</span><select className={fieldClass} value={form.parentContractId || ''} onChange={event => setForm({ ...form, parentContractId: event.target.value || undefined })}><option value="">Select parent contract</option>{contracts.map(item => <option key={item.id} value={item.id}>{item.contractNumber} · {item.title}</option>)}</select></label>}
    <label><span className={labelClass}>Effective date</span><input type="date" className={fieldClass} value={form.effectiveDate || ''} onChange={event => setForm({ ...form, effectiveDate: event.target.value })} /></label>
    <label><span className={labelClass}>Expiry date</span><input type="date" className={fieldClass} value={form.expiryDate || ''} onChange={event => setForm({ ...form, expiryDate: event.target.value })} /></label>
    <label><span className={labelClass}>Notice period (days)</span><input type="number" min="0" className={fieldClass} value={form.noticePeriodDays || 0} onChange={event => setForm({ ...form, noticePeriodDays: Number(event.target.value) })} /></label>
    <label className="flex items-end gap-2 pb-2"><input type="checkbox" checked={Boolean(form.autoRenewal)} onChange={event => setForm({ ...form, autoRenewal: event.target.checked })} className="h-4 w-4" /><span className="text-sm font-medium text-slate-700">Contract automatically renews</span></label>
    {requireTemplate && <label className="md:col-span-2"><span className={labelClass}>Approved template *</span><select className={fieldClass} value={form.templateId || ''} onChange={event => { const template = configuration?.templates.find(item => item.id === event.target.value); setForm({ ...form, templateId: event.target.value, contractType: template?.contractType || form.contractType }); }}><option value="">Select template</option>{configuration?.templates.filter(item => item.approved).map(item => <option key={item.id} value={item.id}>{item.name} · v{item.version}</option>)}</select></label>}
  </div>;
}

function SmartFiles({ openContract }: { openContract: (id: string) => void }) {
  const { configuration, uploadSmartFiles, entities } = useContracts();
  const { user } = useAuth();
  const [form, setForm] = useState<CreateContractInput>(blankInput(configuration));
  const [files, setFiles] = useState<File[]>([]); const [busy, setBusy] = useState(false);
  const [uploadProgress, setUploadProgress] = useState('');
  const [fileTypes, setFileTypes] = useState<Record<number, Contract['documents'][number]['documentType']>>({});
  useEffect(() => { if (entities.length === 1) setForm(current => current.primaryEntityId ? current : { ...current, primaryEntityId: entities[0].id }); }, [entities]);
  const submit = async () => {
    if (!files.length) return toast.error('Select at least one signed contract file.');
    if (files.length > 25) return toast.error('Choose no more than 25 files per upload.');
    const intakeInput = { ...form, title: form.title.trim() || files[0].name.replace(/\.[^.]+$/, '') };
    if (user?.role !== 'GROUP_ADMIN' && !intakeInput.primaryEntityId) return toast.error('Select the legal entity you are permitted to work in.');
    setBusy(true); setUploadProgress('Preparing files…');
    try { const result = await uploadSmartFiles(intakeInput, files.map((file, index) => ({ file, documentType: index === 0 ? 'SIGNED_CONTRACT' : fileTypes[index] || 'SUPPORTING_DOCUMENT', signed: index === 0, authoritative: index === 0 })), (processed, total) => setUploadProgress(`Uploaded ${processed} of ${total} files`)); toast.success('Signed contract preserved; AI review is running in the background.'); openContract(result.contract.id); }
    catch (error) { toast.error(error instanceof Error ? error.message : 'Upload failed.'); } finally { setBusy(false); setUploadProgress(''); }
  };
  return <div className="grid gap-6 xl:grid-cols-[1.15fr_0.85fr]">
    <Card title="Upload signed contracts" icon={Upload}>
      <p className="mb-5 text-sm leading-6 text-slate-600">Start with the signed agreement and any schedules or addenda. The original files stay unchanged while AI proposes the entity, contract profile, clauses and obligations for human review.</p>
      <label><span className={labelClass}>Known legal entity {user?.role === 'GROUP_ADMIN' ? '(optional; AI may propose it)' : '*'}</span><select className={fieldClass} value={form.primaryEntityId} onChange={event => setForm({ ...form, primaryEntityId: event.target.value, businessUnit: '', principalActivity: '', siteOrProject: '' })}><option value="">{user?.role === 'GROUP_ADMIN' ? 'Let AI propose the entity' : 'Select permitted entity'}</option>{entities.filter(item => item.active).map(item => <option key={item.id} value={item.id}>{item.legalName}</option>)}</select></label>
      <div className="mt-5 rounded-2xl border-2 border-dashed border-blue-200 bg-blue-50/40 p-6 text-center">
        <Upload className="mx-auto h-8 w-8 text-blue-700" />
        <div className="mt-2 text-sm font-bold text-blue-950">Signed contract bundle</div>
        <div className="mt-1 text-xs text-slate-500">PDF, Word (.doc/.docx), image, Excel, CSV or text · up to 25 files, 15 MB each</div>
        <label className="mt-4 inline-flex cursor-pointer rounded-xl bg-blue-800 px-4 py-2.5 text-sm font-bold text-white">
          <input type="file" multiple className="hidden" accept=".pdf,.doc,.docx,.png,.jpg,.jpeg,.xlsx,.csv,.txt" onChange={event => { const selected = Array.from(event.target.files || []); if (selected.length > 25) { setFiles([]); toast.error('Choose no more than 25 files per upload.'); } else setFiles(selected); }} />Choose files
        </label>
        {files.length > 0 && <div className="mt-3 space-y-2 text-left">{files.map((file, index) => <div key={`${file.name}-${index}`} className="flex flex-wrap items-center gap-2 rounded-lg bg-white p-2 text-xs"><span className="min-w-0 flex-1 font-bold text-blue-900">{file.name}</span>{index === 0 ? <span className="text-emerald-700">Authoritative signed agreement</span> : <select className="rounded-lg border border-slate-200 p-1" value={fileTypes[index] || 'SUPPORTING_DOCUMENT'} onChange={event => setFileTypes(current => ({ ...current, [index]: event.target.value as Contract['documents'][number]['documentType'] }))}><option value="SUPPORTING_DOCUMENT">Supporting</option><option value="SCHEDULE">Schedule</option><option value="ADDENDUM">Addendum</option><option value="AMENDMENT">Amendment</option><option value="RENEWAL">Renewal</option></select>}</div>)}</div>}
      </div>
      <details className="mt-4 rounded-xl border border-slate-200 p-4"><summary className="cursor-pointer text-sm font-bold text-blue-800">Add known contract details (optional)</summary><p className="my-3 text-xs text-slate-500">AI will propose missing details from the documents. Reviewers must confirm material values, dates and entity mapping before activation.</p><ContractIntakeFields form={form} setForm={setForm} hideEntity documentFirst /></details>
      {files.length > 0 && <p className="mt-2 text-xs text-slate-500">{files.length} of 25 files selected</p>}
      {uploadProgress && <p className="mt-2 text-xs font-bold text-blue-700" role="status">{uploadProgress}</p>}
      <button onClick={submit} disabled={busy || !files.length} className="mt-5 flex w-full items-center justify-center gap-2 rounded-xl bg-blue-800 px-5 py-3 text-sm font-bold text-white disabled:opacity-50">{busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <Sparkles className="h-4 w-4" />}Preserve and analyse contract</button>
    </Card>
    <div className="space-y-6"><Card title="What happens in the background" icon={Bot}><ol className="space-y-4">{['Classify files and contract family', 'Resolve the correct subsidiary and principal activity', 'Extract dates, values, rights and material clauses', 'Turn commitments into entity-owned obligations', 'Calculate notice dates and monitoring alerts', 'Pause for human confirmation before activation'].map((text, index) => <li key={text} className="flex gap-3"><span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-blue-50 text-xs font-black text-blue-700">{index + 1}</span><span className="pt-1 text-sm text-slate-600">{text}</span></li>)}</ol></Card><div className="rounded-2xl border border-amber-200 bg-amber-50 p-5"><div className="flex gap-3"><AlertTriangle className="h-5 w-5 shrink-0 text-amber-700" /><div><div className="font-bold text-amber-900">Human control is mandatory</div><p className="mt-1 text-sm leading-6 text-amber-800">Low-confidence entity matches, material clauses and generated obligations never become active monitoring records until a reviewer confirms them.</p></div></div></div></div>
  </div>;
}

function Drafting({ openContract }: { openContract: (id: string) => void }) {
  const { configuration, contracts, createDraft } = useContracts();
  const [form, setForm] = useState<CreateContractInput>(blankInput(configuration)); const [busy, setBusy] = useState(false);
  const drafts = contracts.filter(contract => contract.source === 'NEW_DRAFT' && !['ACTIVE', 'CLOSED', 'ARCHIVED'].includes(contract.status));
  const submit = async () => {
    if (!form.primaryEntityId || !form.title || !form.counterpartyName || !form.templateId) return toast.error('Complete the title, legal entity, counterparty and template.');
    setBusy(true); try { const contract = await createDraft(form); toast.success('Controlled draft created with company context.'); openContract(contract.id); } catch (error) { toast.error(error instanceof Error ? error.message : 'Draft could not be created.'); } finally { setBusy(false); }
  };
  return <div className="grid gap-6 xl:grid-cols-[1.2fr_0.8fr]"><Card title="Create a new contract" icon={FilePenLine}><p className="mb-5 text-sm leading-6 text-slate-600">Start from approved language, pre-fill the selected entity’s legal context and route the result through controlled drafting, legal review, approval and execution.</p><ContractIntakeFields form={form} setForm={setForm} requireTemplate /><button onClick={submit} disabled={busy} className="mt-5 flex w-full items-center justify-center gap-2 rounded-xl bg-blue-800 px-5 py-3 text-sm font-bold text-white disabled:opacity-50">{busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <FilePenLine className="h-4 w-4" />}Create controlled draft</button></Card><div className="space-y-6"><Card title="Drafts in progress" icon={FileText}><div className="space-y-3">{drafts.map(contract => <button key={contract.id} onClick={() => openContract(contract.id)} className="w-full rounded-xl border border-slate-100 p-3 text-left hover:border-blue-200"><div className="flex items-start justify-between gap-2"><div><div className="text-sm font-bold">{contract.title}</div><div className="mt-1 text-xs text-slate-500">{contract.contractNumber} · v{contract.draftVersions.length}</div></div><Badge value={contract.status} /></div></button>)}{!drafts.length && <div className="rounded-xl border border-dashed p-6 text-center text-sm text-slate-500">No active drafts.</div>}</div></Card><Card title="AI drafting guardrails" icon={ShieldCheck}><ul className="space-y-2 text-sm leading-6 text-slate-600"><li>• Approved templates remain the starting point.</li><li>• Company/entity context is injected before drafting.</li><li>• Every AI change creates a visible version.</li><li>• Legal approval remains required before execution.</li></ul></Card></div></div>;
}

function Register({ openContract }: { openContract: (id: string) => void }) {
  const { contracts, entities } = useContracts(); const [query, setQuery] = useState(''); const [status, setStatus] = useState('ALL');
  const filtered = contracts.filter(contract => `${contract.title} ${contract.contractNumber} ${contract.counterpartyName}`.toLowerCase().includes(query.toLowerCase()) && (status === 'ALL' || contract.status === status));
  return <Card title="Contract register" icon={FileSearch} action={<span className="text-xs text-slate-400">{filtered.length} records</span>}><div className="mb-4 grid gap-3 sm:grid-cols-[1fr_220px]"><label className="relative"><Search className="absolute left-3 top-3 h-4 w-4 text-slate-400" /><input className={`${fieldClass} pl-9`} value={query} onChange={event => setQuery(event.target.value)} placeholder="Search contract, number or counterparty" /></label><select className={fieldClass} value={status} onChange={event => setStatus(event.target.value)}><option value="ALL">All statuses</option>{Array.from(new Set(contracts.map(item => item.status))).map(item => <option key={item}>{clean(item)}</option>)}</select></div><div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left"><thead><tr className="border-b text-[11px] uppercase tracking-wider text-slate-400"><th className="px-3 py-3">Contract</th><th className="px-3 py-3">Entity</th><th className="px-3 py-3">Counterparty</th><th className="px-3 py-3">Owner</th><th className="px-3 py-3">Expiry / notice</th><th className="px-3 py-3">Status</th></tr></thead><tbody>{filtered.map(contract => <tr key={contract.id} onClick={() => openContract(contract.id)} className="cursor-pointer border-b border-slate-50 text-sm hover:bg-blue-50/40"><td className="px-3 py-4"><div className="font-bold text-blue-950">{contract.title}</div><div className="mt-1 text-xs text-slate-400">{contract.contractNumber} · {contract.contractType}</div></td><td className="px-3 py-4 text-slate-600">{entities.find(item => item.id === contract.primaryEntityId)?.displayName || 'Needs mapping'}</td><td className="px-3 py-4 text-slate-600">{contract.counterpartyName || 'Needs review'}</td><td className="px-3 py-4"><div>{contract.owners.contractOwnerName || 'Unassigned'}</div><div className="text-xs text-slate-400">Monitor: {contract.owners.monitoringOwnerName || 'Unassigned'}</div></td><td className="px-3 py-4"><div>{displayDate(contract.expiryDate)}</div><div className="text-xs text-amber-700">Notice {displayDate(contract.noticeDeadline)}</div></td><td className="px-3 py-4"><Badge value={contract.status} /></td></tr>)}</tbody></table></div>{!filtered.length && <div className="py-12 text-center text-sm text-slate-500">No contracts match these filters.</div>}</Card>;
}

function Monitoring({ openContract }: { openContract: (id: string) => void }) {
  const { contracts, dashboard, completeObligation } = useContracts(); const [evidence, setEvidence] = useState<Record<string, string>>({}); const [busy, setBusy] = useState('');
  const obligations = contracts.flatMap(contract => contract.obligations.map(obligation => ({ contract, obligation }))).sort((a, b) => (a.obligation.nextDueDate || a.obligation.dueDate || '9999').localeCompare(b.obligation.nextDueDate || b.obligation.dueDate || '9999'));
  const complete = async (contractId: string, obligation: ContractObligation) => { const note = evidence[obligation.id] || ''; if (!note.trim()) return toast.error('Add completion evidence or a monitoring note.'); setBusy(obligation.id); try { await completeObligation(contractId, obligation.id, note); toast.success(obligation.recurrence && !['ONCE', 'ON_EVENT'].includes(obligation.recurrence) ? 'Cycle completed; next due date created.' : 'Obligation completed.'); } catch (error) { toast.error(error instanceof Error ? error.message : 'Unable to complete obligation.'); } finally { setBusy(''); } };
  return <div className="space-y-6"><div className="grid gap-4 sm:grid-cols-3"><Stat label="Due soon" value={dashboard?.obligationsDueSoon || 0} note="Inside configured alert window" icon={Clock3} tone="amber" /><Stat label="Overdue" value={dashboard?.overdueObligations || 0} note="Escalation required" icon={AlertTriangle} tone="red" /><Stat label="Unassigned" value={dashboard?.unassignedObligations || 0} note="Cannot activate without owners" icon={UserRoundCheck} tone="blue" /></div><Card title="Obligation and commitment register" icon={ClipboardCheck}><div className="space-y-3">{obligations.map(({ contract, obligation }) => <div key={obligation.id} className="rounded-xl border border-slate-100 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><button onClick={() => openContract(contract.id)} className="text-left"><div className="font-bold text-blue-950">{obligation.title}</div><div className="mt-1 text-xs text-slate-500">{contract.title} · {contract.contractNumber}</div></button><div className="text-right"><Badge value={obligation.status} /><div className="mt-1 text-xs text-slate-500">{displayDate(obligation.nextDueDate || obligation.dueDate)}</div></div></div><div className="mt-3 grid gap-3 text-xs sm:grid-cols-3"><div><span className="text-slate-400">Accountable owner</span><div className="mt-1 font-bold">{obligation.ownerName || 'Unassigned'}</div></div><div><span className="text-slate-400">Monitoring owner</span><div className="mt-1 font-bold">{obligation.monitoringOwnerName || 'Unassigned'}</div></div><div><span className="text-slate-400">Evidence required</span><div className="mt-1 font-bold">{obligation.evidenceRequired || 'Completion record'}</div></div></div>{!['COMPLETED', 'WAIVED'].includes(obligation.status) && <div className="mt-3 flex flex-col gap-2 border-t pt-3 sm:flex-row"><input className={fieldClass} value={evidence[obligation.id] || ''} onChange={event => setEvidence(current => ({ ...current, [obligation.id]: event.target.value }))} placeholder="Completion evidence / link / monitoring note" /><button onClick={() => complete(contract.id, obligation)} disabled={busy === obligation.id} className="shrink-0 rounded-xl bg-blue-800 px-4 py-2 text-sm font-bold text-white">{busy === obligation.id ? 'Saving…' : 'Record completion'}</button></div>}</div>)}{!obligations.length && <div className="rounded-xl border border-dashed p-8 text-center text-sm text-slate-500">No obligations have been activated.</div>}</div></Card></div>;
}

const roleOptions: ContractRoleType[] = ['CONTRACT_OWNER', 'MONITORING_OWNER', 'LEGAL_OWNER', 'FINANCE_OWNER', 'COMPLIANCE_OWNER', 'RENEWAL_OWNER', 'ESCALATION_OWNER', 'SIGNATORY'];
const emptyRole = (): Omit<RoleAssignment, 'id'> => ({ role: 'CONTRACT_OWNER', name: '', email: '', department: '' });
const emptyOwnership = (): CorporateOwnershipInterest => ({ ownerEntityId: '', relationship: 'DIRECT' });

function EntityEditorPanel({ entity, onClose }: { entity: CorporateEntity; onClose: () => void }) {
  const { entities, updateEntity } = useContracts(); const [busy, setBusy] = useState(false);
  const [form, setForm] = useState({ ...entity });
  const [text, setText] = useState({ aliases: entity.aliases.join(', '), activities: entity.principalActivities.join(', '), units: entity.businessUnits.join(', '), sites: entity.sites.join(', ') });
  const updateRole = (index: number, values: Partial<RoleAssignment>) => setForm(current => ({ ...current, roleAssignments: current.roleAssignments.map((role, roleIndex) => roleIndex === index ? { ...role, ...values } : role) }));
  const updateOwnership = (index: number, values: Partial<CorporateOwnershipInterest>) => setForm(current => ({ ...current, ownershipInterests: current.ownershipInterests.map((interest, interestIndex) => interestIndex === index ? { ...interest, ...values } : interest) }));
  const save = async () => { setBusy(true); try { await updateEntity(entity.id, { ...form, aliases: text.aliases.split(',').map(item => item.trim()).filter(Boolean), principalActivities: text.activities.split(',').map(item => item.trim()).filter(Boolean), businessUnits: text.units.split(',').map(item => item.trim()).filter(Boolean), sites: text.sites.split(',').map(item => item.trim()).filter(Boolean) }); toast.success('Corporate entity context updated.'); onClose(); } catch (error) { toast.error(error instanceof Error ? error.message : 'Unable to update entity.'); } finally { setBusy(false); } };
  return <Card title="Maintain legal entity" icon={Building2} action={<button onClick={onClose} className="text-xs font-bold text-slate-500">Close</button>}><div className="space-y-3"><label><span className={labelClass}>Operational parent</span><select className={fieldClass} value={form.parentId || ''} onChange={event => setForm({ ...form, parentId: event.target.value || undefined })}><option value="">Top-level entity</option>{entities.filter(item => item.id !== entity.id).map(item => <option key={item.id} value={item.id}>{item.legalName}</option>)}</select><span className="mt-1 block text-xs text-slate-500">Used for workflow ownership and escalation. Shareholding is maintained separately below.</span></label><div className="grid gap-3 sm:grid-cols-2"><label><span className={labelClass}>Legal name</span><input className={fieldClass} value={form.legalName} onChange={event => setForm({ ...form, legalName: event.target.value })} /></label><label><span className={labelClass}>Display name</span><input className={fieldClass} value={form.displayName} onChange={event => setForm({ ...form, displayName: event.target.value })} /></label><label><span className={labelClass}>Registration no. (optional until verified)</span><input className={fieldClass} value={form.registrationNumber} onChange={event => setForm({ ...form, registrationNumber: event.target.value })} /></label><label><span className={labelClass}>Jurisdiction</span><input className={fieldClass} value={form.jurisdiction} onChange={event => setForm({ ...form, jurisdiction: event.target.value })} /></label></div><label><span className={labelClass}>Registered address</span><input className={fieldClass} value={form.registeredAddress} onChange={event => setForm({ ...form, registeredAddress: event.target.value })} /></label><label><span className={labelClass}>Aliases</span><input className={fieldClass} value={text.aliases} onChange={event => setText({ ...text, aliases: event.target.value })} /></label><label><span className={labelClass}>Principal activities</span><input className={fieldClass} value={text.activities} onChange={event => setText({ ...text, activities: event.target.value })} /></label><label><span className={labelClass}>Business units</span><input className={fieldClass} value={text.units} onChange={event => setText({ ...text, units: event.target.value })} /></label><label><span className={labelClass}>Sites / projects</span><input className={fieldClass} value={text.sites} onChange={event => setText({ ...text, sites: event.target.value })} /></label><div className="border-t pt-3"><div className="flex items-center justify-between"><span className="text-sm font-bold text-blue-950">Corporate shareholders</span><button onClick={() => setForm({ ...form, ownershipInterests: [...form.ownershipInterests, emptyOwnership()] })} className="text-xs font-bold text-blue-700">+ Add shareholder</button></div><p className="mt-1 text-xs text-slate-500">Supports joint ventures and multiple shareholders without duplicating the legal entity.</p>{form.ownershipInterests.map((interest, index) => <div key={`${interest.ownerEntityId}-${index}`} className="mt-3 grid gap-2 rounded-xl bg-slate-50 p-3 sm:grid-cols-[1.3fr_0.65fr_0.8fr_auto]"><select className={fieldClass} value={interest.ownerEntityId} onChange={event => updateOwnership(index, { ownerEntityId: event.target.value })}><option value="">Select shareholder</option>{entities.filter(item => item.id !== entity.id).map(item => <option key={item.id} value={item.id}>{item.legalName}</option>)}</select><input type="number" min="0.01" max="100" step="0.01" className={fieldClass} value={interest.percentage ?? ''} onChange={event => updateOwnership(index, { percentage: event.target.value === '' ? undefined : Number(event.target.value) })} placeholder="% pending" /><select className={fieldClass} value={interest.relationship} onChange={event => updateOwnership(index, { relationship: event.target.value as CorporateOwnershipInterest['relationship'] })}><option value="DIRECT">Direct</option><option value="INDIRECT">Indirect</option><option value="JOINT_VENTURE">Joint venture</option><option value="ASSOCIATE">Associate</option><option value="OTHER">Other</option></select><button onClick={() => setForm({ ...form, ownershipInterests: form.ownershipInterests.filter((_, interestIndex) => interestIndex !== index) })} className="rounded-lg border border-red-100 px-3 text-xs font-bold text-red-600">Remove</button></div>)}</div><div className="border-t pt-3"><div className="flex items-center justify-between"><span className="text-sm font-bold text-blue-950">PIC and workflow assignments</span><button onClick={() => setForm({ ...form, roleAssignments: [...form.roleAssignments, { ...emptyRole(), id: crypto.randomUUID() }] })} className="text-xs font-bold text-blue-700">+ Add role</button></div>{form.roleAssignments.map((role, index) => <div key={role.id} className="mt-3 grid gap-2 sm:grid-cols-2"><select className={fieldClass} value={role.role} onChange={event => updateRole(index, { role: event.target.value as ContractRoleType })}>{roleOptions.map(item => <option key={item} value={item}>{clean(item)}</option>)}</select><input className={fieldClass} value={role.name} onChange={event => updateRole(index, { name: event.target.value })} placeholder="Owner name" /><input className={fieldClass} type="email" value={role.email} onChange={event => updateRole(index, { email: event.target.value })} placeholder="Email" /><div className="flex gap-2"><input className={fieldClass} value={role.department} onChange={event => updateRole(index, { department: event.target.value })} placeholder="Department" /><button onClick={() => setForm({ ...form, roleAssignments: form.roleAssignments.filter((_, roleIndex) => roleIndex !== index) })} className="rounded-lg border border-red-100 px-3 text-xs font-bold text-red-600">Remove</button></div></div>)}</div><button onClick={save} disabled={busy || !form.legalName} className="w-full rounded-xl bg-blue-800 py-3 text-sm font-bold text-white disabled:opacity-50">{busy ? 'Saving…' : 'Save entity changes'}</button></div></Card>;
}

const newEntity = (parentId?: string): CreateCorporateEntityInput => ({ parentId, legalName: '', displayName: '', entityType: parentId ? 'SUBSIDIARY' : 'HOLDING_COMPANY', registrationNumber: '', jurisdiction: 'Malaysia', registeredAddress: '', aliases: [], principalActivities: [], businessUnits: [], sites: [], effectiveFrom: new Date().toISOString().slice(0, 10), ownershipInterests: parentId ? [{ ownerEntityId: parentId, relationship: 'DIRECT' }] : [], roleAssignments: [] });

function Structure() {
  const { entities, createEntity, updateEntity } = useContracts();
  const [open, setOpen] = useState(false); const [editingId, setEditingId] = useState(''); const [busy, setBusy] = useState(false); const [insertAboveId, setInsertAboveId] = useState('');
  const [form, setForm] = useState<CreateCorporateEntityInput>(newEntity());
  const [csv, setCsv] = useState({ aliases: '', activities: '', units: '', sites: '' });
  const roots = entities.filter(entity => !entity.parentId); const children = (id: string) => entities.filter(entity => entity.parentId === id);
  const startAdd = (parentId?: string, aboveId = '') => { setForm(newEntity(parentId)); setCsv({ aliases: '', activities: '', units: '', sites: '' }); setInsertAboveId(aboveId); setEditingId(''); setOpen(true); };
  const submit = async () => {
    setBusy(true);
    try {
      const created = await createEntity({ ...form, aliases: csv.aliases.split(',').map(v => v.trim()).filter(Boolean), principalActivities: csv.activities.split(',').map(v => v.trim()).filter(Boolean), businessUnits: csv.units.split(',').map(v => v.trim()).filter(Boolean), sites: csv.sites.split(',').map(v => v.trim()).filter(Boolean) });
      if (insertAboveId) await updateEntity(insertAboveId, { parentId: created.id, ownershipInterests: [{ ownerEntityId: created.id, relationship: 'DIRECT' }] });
      toast.success(insertAboveId ? 'Entity inserted above the selected company.' : 'Legal entity added.'); setOpen(false); setInsertAboveId('');
    } catch (error) { toast.error(error instanceof Error ? error.message : 'Entity could not be created.'); }
    finally { setBusy(false); }
  };
  const editingEntity = entities.find(entity => entity.id === editingId);
  if (editingEntity) return <div className="grid gap-6 xl:grid-cols-[0.7fr_1.3fr]"><Card title="Select entity to maintain" icon={Layers3}><div className="space-y-2">{entities.map(entity => <button key={entity.id} onClick={() => setEditingId(entity.id)} className={`w-full rounded-xl border p-3 text-left ${editingId === entity.id ? 'border-blue-300 bg-blue-50' : 'border-slate-100 hover:border-blue-200'}`}><div className="text-sm font-bold text-blue-950">{entity.legalName}</div><div className="mt-1 text-xs text-slate-500">{clean(entity.entityType)} · {entity.registrationNumber || 'Registration pending'}</div></button>)}</div></Card><EntityEditorPanel entity={editingEntity} onClose={() => setEditingId('')} /></div>;
  const EntityCard = ({ entity, depth = 0 }: { entity: CorporateEntity; depth?: number }) => <div className={depth ? 'ml-5 border-l border-blue-100 pl-4' : ''}><div className="rounded-xl border border-slate-100 bg-white p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-2"><Building2 className="h-4 w-4 text-blue-700" /><span className="font-bold text-blue-950">{entity.legalName}</span></div><div className="mt-1 text-xs text-slate-400">{clean(entity.entityType)} · {entity.registrationNumber || 'Registration pending'} · {entity.jurisdiction}</div><div className="mt-2 text-xs text-slate-500">{entity.ownershipInterests.length} shareholder link(s) · {entity.roleAssignments.length} PIC assignment(s)</div></div><div className="flex flex-wrap items-center gap-2"><button onClick={() => startAdd(entity.id)} className="rounded-lg border border-blue-100 px-3 py-1.5 text-xs font-bold text-blue-700">+ Below</button><button onClick={() => startAdd(entity.parentId, entity.id)} className="rounded-lg border border-blue-100 px-3 py-1.5 text-xs font-bold text-blue-700">+ Above</button><button onClick={() => { setEditingId(entity.id); setOpen(false); }} className="rounded-lg bg-blue-50 px-3 py-1.5 text-xs font-bold text-blue-800">Edit</button><button onClick={async () => { await updateEntity(entity.id, { active: !entity.active }); toast.success(entity.active ? 'Entity archived; its records were retained.' : 'Entity reactivated.'); }} className={`rounded-lg px-3 py-1.5 text-xs font-bold ${entity.active ? 'border border-red-100 text-red-600' : 'bg-emerald-50 text-emerald-700'}`}>{entity.active ? 'Archive / remove from use' : 'Reactivate'}</button></div></div></div><div className="mt-3 space-y-3">{children(entity.id).map(child => <EntityCard key={child.id} entity={child} depth={depth + 1} />)}</div></div>;
  return <div className="space-y-6"><Card title="Manage legal entities" icon={Layers3} action={<button onClick={() => startAdd()} className="flex items-center gap-1 rounded-lg bg-blue-50 px-3 py-2 text-xs font-bold text-blue-800"><Plus className="h-3.5 w-3.5" />Add top-level entity</button>}><p className="mb-4 text-sm text-slate-600">Add a company above or below an existing entity, edit its shareholder links and PICs, or make it inactive. Existing records are retained.</p><div className="space-y-3">{roots.map(entity => <EntityCard key={entity.id} entity={entity} />)}</div></Card>{open && <Card title={insertAboveId ? 'Insert legal entity above' : 'Add legal entity'} icon={Plus}><div className="grid gap-3 sm:grid-cols-2"><label><span className={labelClass}>Operational parent</span><select className={fieldClass} value={form.parentId || ''} onChange={event => setForm({ ...form, parentId: event.target.value || undefined, ownershipInterests: event.target.value ? [{ ownerEntityId: event.target.value, relationship: 'DIRECT' }] : [] })}><option value="">Top-level entity</option>{entities.map(entity => <option key={entity.id} value={entity.id}>{entity.legalName}</option>)}</select></label><label><span className={labelClass}>Entity type</span><select className={fieldClass} value={form.entityType} onChange={event => setForm({ ...form, entityType: event.target.value as CorporateEntity['entityType'] })}><option value="SUBSIDIARY">Subsidiary</option><option value="HOLDING_COMPANY">Holding company</option><option value="JOINT_VENTURE">Joint venture</option><option value="GROUP">Group</option><option value="OTHER">Other</option></select></label><label><span className={labelClass}>Legal name *</span><input className={fieldClass} value={form.legalName} onChange={event => setForm({ ...form, legalName: event.target.value })} /></label><label><span className={labelClass}>Display name</span><input className={fieldClass} value={form.displayName} onChange={event => setForm({ ...form, displayName: event.target.value })} /></label><label><span className={labelClass}>Registration no. (optional)</span><input className={fieldClass} value={form.registrationNumber || ''} onChange={event => setForm({ ...form, registrationNumber: event.target.value })} /></label><label><span className={labelClass}>Principal activities</span><input className={fieldClass} value={csv.activities} onChange={event => setCsv({ ...csv, activities: event.target.value })} placeholder="Comma-separated" /></label></div><div className="mt-4 flex justify-end gap-2"><button onClick={() => { setOpen(false); setInsertAboveId(''); }} className="px-4 py-2 text-sm font-bold text-slate-500">Cancel</button><button onClick={submit} disabled={busy || !form.legalName.trim()} className="rounded-xl bg-blue-800 px-5 py-2.5 text-sm font-bold text-white disabled:opacity-50">{busy ? 'Saving…' : 'Add entity'}</button></div></Card>}</div>;
}

function Configuration() {
  const { configuration, entities, addPlaybookRule } = useContracts();
  const [showBuilder, setShowBuilder] = useState(false); const [busy, setBusy] = useState(false);
  const [form, setForm] = useState<Partial<ContractPlaybookRule>>({ name: '', clauseType: 'Compliance', applicableContractTypes: [], entityIds: [], principalActivities: [], required: true, preferredPosition: '', redFlagTerms: [], risk: 'HIGH', ownerRole: 'Legal', active: true });
  const [redFlags, setRedFlags] = useState(''); const [activities, setActivities] = useState('');
  const toggleList = (key: 'applicableContractTypes' | 'entityIds', value: string) => setForm(current => ({ ...current, [key]: (current[key] || []).includes(value) ? (current[key] || []).filter(item => item !== value) : [...(current[key] || []), value] }));
  const submit = async () => {
    setBusy(true);
    try {
      const result = await addPlaybookRule({ ...form, redFlagTerms: redFlags.split(',').map(item => item.trim()).filter(Boolean), principalActivities: activities.split(',').map(item => item.trim()).filter(Boolean) });
      toast.success(`Playbook v${result.configuration.playbookVersion} published${result.affectedContracts.length ? `; ${result.affectedContracts.length} contract(s) need review` : ''}.`);
      setShowBuilder(false); setForm({ name: '', clauseType: 'Compliance', applicableContractTypes: [], entityIds: [], principalActivities: [], required: true, preferredPosition: '', redFlagTerms: [], risk: 'HIGH', ownerRole: 'Legal', active: true }); setRedFlags(''); setActivities('');
    } catch (error) { toast.error(error instanceof Error ? error.message : 'Unable to publish playbook rule.'); }
    finally { setBusy(false); }
  };
  return <div className="space-y-6"><Card title={`Clause playbook · version ${configuration?.playbookVersion || 1}`} icon={ShieldCheck} action={<button onClick={() => setShowBuilder(value => !value)} className="flex items-center gap-1 rounded-lg bg-blue-50 px-3 py-2 text-xs font-bold text-blue-800"><Plus className="h-3.5 w-3.5" />Add rule</button>}><p className="mb-4 text-sm leading-6 text-slate-600">Configure what language is required, the company’s preferred position and terms that must be escalated. Rules can target contract types, legal entities and principal activities without code changes.</p>{showBuilder && <div className="mb-5 rounded-2xl border border-blue-100 bg-blue-50/30 p-4"><div className="grid gap-3 sm:grid-cols-2"><label><span className={labelClass}>Rule name *</span><input className={fieldClass} value={form.name || ''} onChange={event => setForm({ ...form, name: event.target.value })} /></label><label><span className={labelClass}>Clause type *</span><select className={fieldClass} value={form.clauseType} onChange={event => setForm({ ...form, clauseType: event.target.value })}>{configuration?.clauseTypes.map(type => <option key={type}>{type}</option>)}</select></label><label><span className={labelClass}>Risk if breached</span><select className={fieldClass} value={form.risk} onChange={event => setForm({ ...form, risk: event.target.value as ContractPlaybookRule['risk'] })}><option>LOW</option><option>MEDIUM</option><option>HIGH</option><option>CRITICAL</option></select></label><label><span className={labelClass}>Review owner role</span><input className={fieldClass} value={form.ownerRole || ''} onChange={event => setForm({ ...form, ownerRole: event.target.value })} /></label><label className="sm:col-span-2"><span className={labelClass}>Preferred company position *</span><textarea rows={2} className={fieldClass} value={form.preferredPosition || ''} onChange={event => setForm({ ...form, preferredPosition: event.target.value })} /></label><label><span className={labelClass}>Red-flag phrases (comma-separated)</span><input className={fieldClass} value={redFlags} onChange={event => setRedFlags(event.target.value)} placeholder="unlimited liability, without notice" /></label><label><span className={labelClass}>Principal activities (comma-separated)</span><input className={fieldClass} value={activities} onChange={event => setActivities(event.target.value)} placeholder="Construction, Facilities management" /></label></div><div className="mt-3"><span className={labelClass}>Applicable contract types · none means all</span><div className="flex flex-wrap gap-2">{configuration?.contractTypes.map(type => <button type="button" key={type} onClick={() => toggleList('applicableContractTypes', type)} className={`rounded-lg border px-2.5 py-1.5 text-xs font-bold ${(form.applicableContractTypes || []).includes(type) ? 'border-blue-300 bg-blue-50 text-blue-800' : 'border-slate-200 bg-white text-slate-500'}`}>{type}</button>)}</div></div><div className="mt-3"><span className={labelClass}>Applicable entities · none means group-wide</span><div className="flex flex-wrap gap-2">{entities.map(entity => <button type="button" key={entity.id} onClick={() => toggleList('entityIds', entity.id)} className={`rounded-lg border px-2.5 py-1.5 text-xs font-bold ${(form.entityIds || []).includes(entity.id) ? 'border-blue-300 bg-blue-50 text-blue-800' : 'border-slate-200 bg-white text-slate-500'}`}>{entity.displayName}</button>)}</div></div><label className="mt-4 flex items-center gap-2 text-sm font-bold text-slate-700"><input type="checkbox" checked={Boolean(form.required)} onChange={event => setForm({ ...form, required: event.target.checked })} />Clause is mandatory when this rule applies</label><div className="mt-4 flex justify-end gap-2"><button onClick={() => setShowBuilder(false)} className="px-3 py-2 text-xs font-bold text-slate-500">Cancel</button><button onClick={submit} disabled={busy || !form.name || !form.preferredPosition} className="rounded-lg bg-blue-800 px-4 py-2 text-xs font-bold text-white disabled:opacity-50">{busy ? 'Publishing…' : 'Publish rule'}</button></div></div>}<div className="grid gap-3 lg:grid-cols-2">{configuration?.playbookRules.map(rule => <div key={rule.id} className="rounded-xl border border-slate-100 p-4"><div className="flex items-start justify-between gap-3"><div><div className="font-bold text-blue-950">{rule.name}</div><div className="mt-1 text-xs text-slate-400">{rule.clauseType} · owner: {rule.ownerRole}</div></div><Badge value={rule.risk} /></div><p className="mt-3 text-sm leading-6 text-slate-600">{rule.preferredPosition}</p><div className="mt-3 flex flex-wrap gap-1.5">{rule.required && <span className="rounded bg-red-50 px-2 py-1 text-[10px] font-bold text-red-700">Required</span>}{rule.applicableContractTypes.length ? rule.applicableContractTypes.map(type => <span key={type} className="rounded bg-slate-50 px-2 py-1 text-[10px] font-bold text-slate-600">{type}</span>) : <span className="rounded bg-slate-50 px-2 py-1 text-[10px] font-bold text-slate-600">All contract types</span>}</div>{rule.redFlagTerms.length > 0 && <div className="mt-2 text-xs text-amber-700">Flags: {rule.redFlagTerms.join(', ')}</div>}</div>)}</div></Card><div className="grid gap-6 xl:grid-cols-2"><Card title="Approved templates" icon={FileCheck2}><div className="space-y-3">{configuration?.templates.map(template => <div key={template.id} className="rounded-xl border border-slate-100 p-4"><div className="flex justify-between"><div><div className="font-bold text-blue-950">{template.name}</div><div className="mt-1 text-xs text-slate-400">{template.contractType} · version {template.version}</div></div><Badge value={template.approved ? 'APPROVED' : 'DRAFT'} /></div><p className="mt-2 text-sm text-slate-600">{template.description}</p></div>)}</div></Card><div className="space-y-6"><Card title="Approval matrix" icon={UserRoundCheck}><div className="space-y-3">{configuration?.approvalStages.map((stage, index) => <div key={stage.id} className="flex items-center gap-3"><span className="flex h-8 w-8 items-center justify-center rounded-full bg-blue-50 text-xs font-black text-blue-700">{index + 1}</span><div><div className="text-sm font-bold">{stage.name}</div><div className="text-xs text-slate-500">{stage.role}{stage.valueThreshold ? ` · above MYR ${stage.valueThreshold.toLocaleString()}` : ''}</div></div></div>)}</div></Card><Card title="Monitoring policy" icon={BellRing}><div className="text-sm text-slate-600">Alerts are created at:</div><div className="mt-3 flex flex-wrap gap-2">{configuration?.alertDays.map(days => <span key={days} className="rounded-lg bg-amber-50 px-3 py-2 text-xs font-bold text-amber-800">{days === 0 ? 'Due date' : `${days} days before`}</span>)}</div></Card></div></div></div>;
}

function ContractMappingEditor({ contract }: { contract: Contract }) {
  const { entities, updateContract } = useContracts();
  const { vendors } = useVendors();
  const [form, setForm] = useState({
    primaryEntityId: contract.primaryEntityId, coveredEntityIds: contract.coveredEntityIds,
    principalActivity: contract.principalActivity, businessUnit: contract.businessUnit, siteOrProject: contract.siteOrProject, vendorId: contract.vendorId || '',
  });
  const [busy, setBusy] = useState(false);
  useEffect(() => setForm({ primaryEntityId: contract.primaryEntityId, coveredEntityIds: contract.coveredEntityIds, principalActivity: contract.principalActivity, businessUnit: contract.businessUnit, siteOrProject: contract.siteOrProject, vendorId: contract.vendorId || '' }), [contract]);
  const entity = entities.find(item => item.id === form.primaryEntityId);
  const toggleCovered = (id: string) => setForm(current => ({ ...current, coveredEntityIds: current.coveredEntityIds.includes(id) ? current.coveredEntityIds.filter(item => item !== id) : [...current.coveredEntityIds, id] }));
  const save = async () => {
    setBusy(true);
    try { await updateContract(contract.id, form as Partial<Contract>); toast.success('Entity and operating context confirmed.'); }
    catch (error) { toast.error(error instanceof Error ? error.message : 'Unable to save entity mapping.'); }
    finally { setBusy(false); }
  };
  return <div className="space-y-4"><div className="grid gap-3 sm:grid-cols-2">
    <label><span className={labelClass}>Signing legal entity *</span><select className={fieldClass} value={form.primaryEntityId} onChange={event => setForm({ ...form, primaryEntityId: event.target.value, coveredEntityIds: event.target.value ? [event.target.value] : [], principalActivity: '', businessUnit: '', siteOrProject: '', vendorId: '' })}><option value="">Needs entity review</option>{entities.filter(item => item.active).map(item => <option key={item.id} value={item.id}>{item.legalName}</option>)}</select></label>
    <label><span className={labelClass}>Principal activity</span><select className={fieldClass} value={form.principalActivity} onChange={event => setForm({ ...form, principalActivity: event.target.value })}><option value="">Not assigned</option>{entity?.principalActivities.map(item => <option key={item}>{item}</option>)}</select></label>
    <label><span className={labelClass}>Business unit</span><select className={fieldClass} value={form.businessUnit} onChange={event => setForm({ ...form, businessUnit: event.target.value })}><option value="">Not assigned</option>{entity?.businessUnits.map(item => <option key={item}>{item}</option>)}</select></label>
    <label><span className={labelClass}>Site / project</span><select className={fieldClass} value={form.siteOrProject} onChange={event => setForm({ ...form, siteOrProject: event.target.value })}><option value="">Not site-specific</option>{entity?.sites.map(item => <option key={item}>{item}</option>)}</select></label>
  </div><div><span className={labelClass}>Other entities covered by this contract</span><div className="flex flex-wrap gap-2">{entities.filter(item => item.active).map(item => <label key={item.id} className={`flex cursor-pointer items-center gap-2 rounded-lg border px-3 py-2 text-xs font-bold ${form.coveredEntityIds.includes(item.id) ? 'border-blue-300 bg-blue-50 text-blue-800' : 'border-slate-200 text-slate-500'}`}><input type="checkbox" className="h-3.5 w-3.5" checked={form.coveredEntityIds.includes(item.id)} onChange={() => toggleCovered(item.id)} />{item.displayName}</label>)}</div></div><label><span className={labelClass}>Linked vendor</span><select className={fieldClass} value={form.vendorId} onChange={event => setForm({ ...form, vendorId: event.target.value })}><option value="">No vendor link</option>{vendors.filter(vendor => [form.primaryEntityId, ...form.coveredEntityIds].includes(vendor.entityId || '')).map(vendor => <option key={vendor.id} value={vendor.id}>{vendor.legalName} · {vendor.registrationNumber}</option>)}</select><span className="mt-1 block text-xs text-slate-500">The counterparty registration number must match the vendor. Vendor compliance reads this contract’s status and expiry.</span></label><div className="flex justify-end"><button onClick={save} disabled={busy || !form.primaryEntityId} className="rounded-xl bg-blue-800 px-4 py-2.5 text-sm font-bold text-white disabled:opacity-50">{busy ? 'Saving…' : 'Confirm entity mapping'}</button></div></div>;
}

function ContractMetadataEditor({ contract }: { contract: Contract }) {
  const { configuration, updateContract } = useContracts(); const [editing, setEditing] = useState(false); const [busy, setBusy] = useState(false);
  const [form, setForm] = useState({ title: contract.title, contractType: contract.contractType, counterpartyName: contract.counterpartyName, counterpartyRegistrationNumber: contract.counterpartyRegistrationNumber, purpose: contract.purpose, value: contract.value, currency: contract.currency, effectiveDate: contract.effectiveDate || '', expiryDate: contract.expiryDate || '', noticePeriodDays: contract.noticePeriodDays || 0, autoRenewal: contract.autoRenewal });
  useEffect(() => setForm({ title: contract.title, contractType: contract.contractType, counterpartyName: contract.counterpartyName, counterpartyRegistrationNumber: contract.counterpartyRegistrationNumber, purpose: contract.purpose, value: contract.value, currency: contract.currency, effectiveDate: contract.effectiveDate || '', expiryDate: contract.expiryDate || '', noticePeriodDays: contract.noticePeriodDays || 0, autoRenewal: contract.autoRenewal }), [contract]);
  const save = async () => { setBusy(true); try { await updateContract(contract.id, form as Partial<Contract>); toast.success('Contract metadata and key dates updated.'); setEditing(false); } catch (error) { toast.error(error instanceof Error ? error.message : 'Unable to save metadata.'); } finally { setBusy(false); } };
  if (!editing) return <div><div className="grid gap-4 sm:grid-cols-2">{[['Value', `${contract.currency} ${contract.value.toLocaleString()}`], ['Effective', displayDate(contract.effectiveDate)], ['Expiry', displayDate(contract.expiryDate)], ['Notice deadline', displayDate(contract.noticeDeadline)], ['Auto-renewal', contract.autoRenewal ? 'Yes' : 'No'], ['Counterparty', contract.counterpartyName || 'Needs review']].map(([label, value]) => <div key={label}><div className="text-xs text-slate-400">{label}</div><div className="mt-1 text-sm font-bold text-slate-800">{value}</div></div>)}</div><button onClick={() => setEditing(true)} className="mt-4 rounded-lg bg-blue-50 px-3 py-2 text-xs font-bold text-blue-800">Review extracted metadata</button></div>;
  return <div className="grid gap-3 sm:grid-cols-2"><label className="sm:col-span-2"><span className={labelClass}>Contract title</span><input className={fieldClass} value={form.title} onChange={event => setForm({ ...form, title: event.target.value })} /></label><label><span className={labelClass}>Contract type</span><select className={fieldClass} value={form.contractType} onChange={event => setForm({ ...form, contractType: event.target.value })}>{configuration?.contractTypes.map(type => <option key={type}>{type}</option>)}</select></label><label><span className={labelClass}>Counterparty</span><input className={fieldClass} value={form.counterpartyName} onChange={event => setForm({ ...form, counterpartyName: event.target.value })} /></label><label><span className={labelClass}>Counterparty registration</span><input className={fieldClass} value={form.counterpartyRegistrationNumber} onChange={event => setForm({ ...form, counterpartyRegistrationNumber: event.target.value })} /></label><label><span className={labelClass}>Value</span><div className="flex"><select className="rounded-l-xl border border-r-0 border-slate-200 bg-slate-50 px-2 text-xs" value={form.currency} onChange={event => setForm({ ...form, currency: event.target.value })}><option>MYR</option><option>USD</option><option>SGD</option></select><input type="number" className={`${fieldClass} rounded-l-none`} value={form.value} onChange={event => setForm({ ...form, value: Number(event.target.value) })} /></div></label><label><span className={labelClass}>Effective date</span><input type="date" className={fieldClass} value={form.effectiveDate} onChange={event => setForm({ ...form, effectiveDate: event.target.value })} /></label><label><span className={labelClass}>Expiry date</span><input type="date" className={fieldClass} value={form.expiryDate} onChange={event => setForm({ ...form, expiryDate: event.target.value })} /></label><label><span className={labelClass}>Notice period days</span><input type="number" className={fieldClass} value={form.noticePeriodDays} onChange={event => setForm({ ...form, noticePeriodDays: Number(event.target.value) })} /></label><label className="flex items-end gap-2 pb-2"><input type="checkbox" checked={form.autoRenewal} onChange={event => setForm({ ...form, autoRenewal: event.target.checked })} />Automatically renews</label><label className="sm:col-span-2"><span className={labelClass}>Purpose</span><textarea rows={2} className={fieldClass} value={form.purpose} onChange={event => setForm({ ...form, purpose: event.target.value })} /></label><div className="flex justify-end gap-2 sm:col-span-2"><button onClick={() => setEditing(false)} className="px-3 py-2 text-xs font-bold text-slate-500">Cancel</button><button onClick={save} disabled={busy || !form.title} className="rounded-lg bg-blue-800 px-4 py-2 text-xs font-bold text-white">{busy ? 'Saving…' : 'Save metadata'}</button></div></div>;
}

function OwnerEditor({ contract }: { contract: Contract }) {
  const { updateContract } = useContracts(); const [owners, setOwners] = useState(contract.owners); const [busy, setBusy] = useState(false);
  useEffect(() => setOwners(contract.owners), [contract]);
  const save = async () => { setBusy(true); try { await updateContract(contract.id, { owners } as Partial<Contract>); toast.success('Contract and monitoring ownership updated.'); } catch (error) { toast.error(error instanceof Error ? error.message : 'Unable to update owners.'); } finally { setBusy(false); } };
  const pairs: Array<[keyof typeof owners, string]> = [['contractOwnerName', 'Contract owner'], ['contractOwnerEmail', 'Contract owner email'], ['monitoringOwnerName', 'Monitoring owner'], ['monitoringOwnerEmail', 'Monitoring owner email'], ['legalOwnerName', 'Legal owner'], ['legalOwnerEmail', 'Legal owner email'], ['renewalOwnerName', 'Renewal owner'], ['renewalOwnerEmail', 'Renewal owner email']];
  return <div><div className="grid gap-3 sm:grid-cols-2">{pairs.map(([key, label]) => <label key={key}><span className={labelClass}>{label}</span><input className={fieldClass} value={owners[key]} onChange={event => setOwners({ ...owners, [key]: event.target.value })} /></label>)}</div><div className="mt-3 flex justify-end"><button onClick={save} disabled={busy} className="rounded-xl bg-blue-800 px-4 py-2.5 text-sm font-bold text-white">{busy ? 'Saving…' : 'Save ownership'}</button></div></div>;
}

function ObligationEditor({ contract, obligation }: { contract: Contract; obligation: ContractObligation }) {
  const { entities, updateObligation } = useContracts();
  const [editing, setEditing] = useState(false); const [busy, setBusy] = useState(false); const [form, setForm] = useState(obligation);
  useEffect(() => setForm(obligation), [obligation]);
  const save = async () => { setBusy(true); try { await updateObligation(contract.id, obligation.id, form); toast.success('Obligation mapping and ownership updated.'); setEditing(false); } catch (error) { toast.error(error instanceof Error ? error.message : 'Unable to save obligation.'); } finally { setBusy(false); } };
  if (!editing) return <div className="rounded-xl border border-slate-100 p-4"><div className="flex flex-wrap justify-between gap-3"><div><div className="font-bold text-blue-950">{obligation.title}</div><div className="mt-1 text-xs text-slate-500">{entities.find(item => item.id === obligation.entityId)?.legalName || 'Entity needs mapping'} · {clean(obligation.responsibleParty)}</div></div><div className="text-right"><Badge value={obligation.status} /><div className="mt-1 text-xs text-slate-500">{displayDate(obligation.nextDueDate || obligation.dueDate)}</div></div></div><p className="mt-3 text-sm text-slate-600">{obligation.action}</p><div className="mt-3 grid gap-3 rounded-lg bg-slate-50 p-3 text-xs sm:grid-cols-3"><div><span className="text-slate-400">Accountable</span><div className="font-bold">{obligation.ownerName || 'Unassigned'}</div></div><div><span className="text-slate-400">Monitored by</span><div className="font-bold">{obligation.monitoringOwnerName || 'Unassigned'}</div></div><div><span className="text-slate-400">Evidence</span><div className="font-bold">{obligation.evidenceRequired}</div></div></div><div className="mt-3 flex justify-end"><button onClick={() => setEditing(true)} className="rounded-lg bg-blue-50 px-3 py-2 text-xs font-bold text-blue-800">Review mapping and owners</button></div></div>;
  return <div className="rounded-xl border border-blue-200 bg-blue-50/20 p-4"><div className="grid gap-3 sm:grid-cols-2"><label className="sm:col-span-2"><span className={labelClass}>Obligation title</span><input className={fieldClass} value={form.title} onChange={event => setForm({ ...form, title: event.target.value })} /></label><label className="sm:col-span-2"><span className={labelClass}>Required action</span><textarea rows={2} className={fieldClass} value={form.action} onChange={event => setForm({ ...form, action: event.target.value })} /></label><label><span className={labelClass}>Applicable entity</span><select className={fieldClass} value={form.entityId} onChange={event => setForm({ ...form, entityId: event.target.value })}>{entities.map(item => <option key={item.id} value={item.id}>{item.legalName}</option>)}</select></label><label><span className={labelClass}>Due / next due</span><input type="date" className={fieldClass} value={form.nextDueDate || form.dueDate || ''} onChange={event => form.recurrence && !['ONCE', 'ON_EVENT'].includes(form.recurrence) ? setForm({ ...form, nextDueDate: event.target.value }) : setForm({ ...form, dueDate: event.target.value })} /></label><label><span className={labelClass}>Accountable owner</span><input className={fieldClass} value={form.ownerName} onChange={event => setForm({ ...form, ownerName: event.target.value })} /></label><label><span className={labelClass}>Owner email</span><input type="email" className={fieldClass} value={form.ownerEmail} onChange={event => setForm({ ...form, ownerEmail: event.target.value })} /></label><label><span className={labelClass}>Monitoring owner</span><input className={fieldClass} value={form.monitoringOwnerName} onChange={event => setForm({ ...form, monitoringOwnerName: event.target.value })} /></label><label><span className={labelClass}>Monitoring email</span><input type="email" className={fieldClass} value={form.monitoringOwnerEmail} onChange={event => setForm({ ...form, monitoringOwnerEmail: event.target.value })} /></label><label><span className={labelClass}>Recurrence</span><select className={fieldClass} value={form.recurrence || 'ON_EVENT'} onChange={event => setForm({ ...form, recurrence: event.target.value as ContractObligation['recurrence'] })}><option value="ONCE">Once</option><option value="MONTHLY">Monthly</option><option value="QUARTERLY">Quarterly</option><option value="ANNUALLY">Annually</option><option value="ON_EVENT">On event</option></select></label><label><span className={labelClass}>Evidence required</span><input className={fieldClass} value={form.evidenceRequired} onChange={event => setForm({ ...form, evidenceRequired: event.target.value })} /></label></div><div className="mt-3 flex justify-end gap-2"><button onClick={() => setEditing(false)} className="px-3 py-2 text-xs font-bold text-slate-500">Cancel</button><button onClick={save} disabled={busy} className="rounded-lg bg-blue-800 px-4 py-2 text-xs font-bold text-white">{busy ? 'Saving…' : 'Confirm obligation'}</button></div></div>;
}

function DraftEditor({ contract }: { contract: Contract }) {
  const { configuration, saveDraft, aiDraft, submitReview, decideApproval, uploadDocuments, markExecuted } = useContracts(); const [content, setContent] = useState(contract.draftContent); const [instruction, setInstruction] = useState(''); const [summary, setSummary] = useState(''); const [busy, setBusy] = useState(''); const [signed, setSigned] = useState<File[]>([]);
  useEffect(() => setContent(contract.draftContent), [contract.draftContent]);
  const run = async (action: string, callback: () => Promise<unknown>, success: string) => { setBusy(action); try { await callback(); toast.success(success); } catch (error) { toast.error(error instanceof Error ? error.message : 'Action failed.'); } finally { setBusy(''); } };
  const latestSubmission = contract.approvals.reduce((last, event, index) => event.decision === 'SUBMITTED' ? index : last, -1);
  const cycle = contract.approvals.slice(latestSubmission + 1);
  const pendingStage = configuration?.approvalStages.filter(stage => stage.valueThreshold === undefined || contract.value >= stage.valueThreshold).find(stage => !cycle.some(event => event.stage === stage.name && event.decision === 'APPROVED'));
  return <><div className="space-y-4"><div className="flex flex-wrap gap-2"><Badge value={contract.status} /><span className="rounded-full bg-slate-100 px-2.5 py-1 text-[11px] font-bold text-slate-600">Version {contract.draftVersions.length}</span></div><textarea className="min-h-[520px] w-full rounded-2xl border border-slate-200 bg-white p-5 font-mono text-sm leading-7 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100" value={content} disabled={contract.status !== 'DRAFT'} onChange={event => setContent(event.target.value)} /><div className="grid gap-3 md:grid-cols-[1fr_auto]"><input className={fieldClass} value={summary} onChange={event => setSummary(event.target.value)} placeholder="Change summary for version history" /><button onClick={() => run('save', () => saveDraft(contract.id, content, summary), 'Draft version saved.')} disabled={!!busy || contract.status !== 'DRAFT'} className="flex items-center justify-center gap-2 rounded-xl bg-slate-900 px-4 py-2.5 text-sm font-bold text-white"><Save className="h-4 w-4" />Save version</button></div><div className="rounded-2xl border border-blue-100 bg-blue-50/40 p-4"><div className="flex items-center gap-2 font-bold text-blue-950"><Sparkles className="h-4 w-4" />AI drafting assistant</div><p className="mt-1 text-xs text-slate-500">AI creates a new visible version. It does not approve legal terms.</p><div className="mt-3 flex flex-col gap-2 md:flex-row"><input className={fieldClass} value={instruction} onChange={event => setInstruction(event.target.value)} placeholder="e.g. Add a Malaysian PDPA incident notification clause" /><button onClick={() => run('ai', async () => { const updated = await aiDraft(contract.id, instruction); setContent(updated.draftContent); setInstruction(''); }, 'AI-assisted version created.')} disabled={!!busy || contract.status !== 'DRAFT' || !instruction.trim()} className="shrink-0 rounded-xl bg-blue-800 px-4 py-2.5 text-sm font-bold text-white">{busy === 'ai' ? 'Drafting…' : 'Generate revision'}</button></div></div><div className="flex flex-wrap gap-2">{['DRAFT'].includes(contract.status) && <button onClick={() => run('review', () => submitReview(contract.id, 'Draft ready for the approval workflow.'), 'Draft submitted for staged approval.')} className="flex items-center gap-2 rounded-xl bg-indigo-700 px-4 py-2.5 text-sm font-bold text-white"><Send className="h-4 w-4" />Submit approval workflow</button>}{['LEGAL_REVIEW', 'APPROVAL_PENDING'].includes(contract.status) && <><button onClick={() => run('approve', () => decideApproval(contract.id, 'APPROVED', `${pendingStage?.name || 'Approval'} approved.`), 'Approval stage recorded.')} className="rounded-xl bg-emerald-700 px-4 py-2.5 text-sm font-bold text-white">{`Approve ${pendingStage?.name || 'stage'}`}</button><button onClick={() => run('return', () => decideApproval(contract.id, 'RETURNED', 'Returned for drafting changes.'), 'Contract returned to drafting.')} className="rounded-xl bg-amber-100 px-4 py-2.5 text-sm font-bold text-amber-800">Return</button></>}{contract.status === 'APPROVED' && <div className="flex w-full flex-col gap-2 rounded-xl border border-teal-100 bg-teal-50 p-4 sm:flex-row"><label className="flex-1 cursor-pointer rounded-xl border border-dashed border-teal-300 px-4 py-2.5 text-sm font-bold text-teal-800"><input type="file" className="hidden" accept=".pdf,.png,.jpg,.jpeg,.docx" onChange={event => setSigned(Array.from(event.target.files || []))} />{signed[0]?.name || 'Choose authoritative signed version'}</label><button onClick={() => run('execute', async () => { if (!signed.length) throw new Error('Choose the signed contract first.'); await uploadDocuments(contract.id, signed.map(file => ({ file, documentType: 'SIGNED_CONTRACT', signed: true, authoritative: true }))); }, 'Signed version preserved and queued for intelligence.')} className="rounded-xl bg-teal-700 px-4 py-2.5 text-sm font-bold text-white">Upload signed version</button>{contract.documents.some(item => item.signed && item.authoritative) && <button onClick={() => run('mark', () => markExecuted(contract.id), 'Contract marked executed.')} className="rounded-xl bg-blue-950 px-4 py-2.5 text-sm font-bold text-white">Mark executed</button>}</div>}</div></div><DraftHistory contract={contract} /></>;
}

function ClauseCard({ contract, clause }: { contract: Contract; clause: ContractClause }) {
  const { reviewClause } = useContracts(); const [busy, setBusy] = useState(false);
  const decide = async (reviewStatus: ContractClause['reviewStatus']) => { setBusy(true); try { await reviewClause(contract.id, clause.id, { reviewStatus }); toast.success(reviewStatus === 'CONFIRMED' ? 'Clause confirmed.' : 'Clause flagged for correction.'); } catch (error) { toast.error(error instanceof Error ? error.message : 'Unable to review clause.'); } finally { setBusy(false); } };
  return <div className="rounded-xl border border-slate-100 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="text-xs font-bold uppercase tracking-wide text-slate-400">Clause {clause.clauseNumber || '—'} · {clause.clauseType}</div><div className="mt-1 font-bold text-blue-950">{clause.heading}</div></div><div className="flex gap-2"><Badge value={clause.risk} /><Badge value={clause.reviewStatus} /></div></div><p className="mt-3 text-sm leading-6 text-slate-600">{clause.sourceText}</p><div className="mt-2 text-xs text-slate-400">{clause.sourceReference} · AI confidence {Math.round(clause.confidence * 100)}% · {clean(clause.responsibleParty)}</div>{clause.reviewStatus !== 'CONFIRMED' && <div className="mt-3 flex gap-2"><button disabled={busy} onClick={() => decide('CONFIRMED')} className="flex items-center gap-1 rounded-lg bg-emerald-50 px-3 py-2 text-xs font-bold text-emerald-700"><Check className="h-3.5 w-3.5" />Confirm extraction</button><button disabled={busy} onClick={() => decide('REVIEW_REQUIRED')} className="rounded-lg bg-purple-50 px-3 py-2 text-xs font-bold text-purple-700">Needs correction</button></div>}</div>;
}

function ReviewIssueCard({ contract, issue }: { contract: Contract; issue: Contract['reviewIssues'][number] }) {
  const { resolveReviewIssue } = useContracts(); const [resolution, setResolution] = useState(issue.resolution || ''); const [busy, setBusy] = useState(false);
  const decide = async (decision: 'ACCEPTED' | 'RESOLVED') => { if (!resolution.trim()) return toast.error('Enter the remediation evidence or exception rationale.'); setBusy(true); try { await resolveReviewIssue(contract.id, issue.id, decision, resolution); toast.success(decision === 'ACCEPTED' ? 'Risk exception accepted and audited.' : 'Playbook issue resolved.'); } catch (error) { toast.error(error instanceof Error ? error.message : 'Unable to close issue.'); } finally { setBusy(false); } };
  return <div className={`rounded-xl border p-4 ${issue.status === 'OPEN' ? 'border-amber-200 bg-amber-50/50' : 'border-green-100 bg-green-50/40'}`}><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="text-xs font-bold uppercase tracking-wide text-slate-400">{clean(issue.type)} · owner: {issue.ownerRole}</div><div className="mt-1 font-bold text-slate-900">{issue.title}</div></div><div className="flex gap-2"><Badge value={issue.severity} /><Badge value={issue.status} /></div></div><p className="mt-2 text-sm leading-6 text-slate-600">{issue.detail}</p>{issue.status === 'OPEN' ? <div className="mt-3 flex flex-col gap-2 border-t border-amber-100 pt-3 sm:flex-row"><input className={fieldClass} value={resolution} onChange={event => setResolution(event.target.value)} placeholder="Remediation evidence or approved exception rationale" /><button disabled={busy} onClick={() => decide('RESOLVED')} className="shrink-0 rounded-lg bg-emerald-700 px-3 py-2 text-xs font-bold text-white">Resolve</button><button disabled={busy} onClick={() => decide('ACCEPTED')} className="shrink-0 rounded-lg bg-amber-700 px-3 py-2 text-xs font-bold text-white">Accept risk</button></div> : <div className="mt-3 text-xs font-medium text-green-700">{issue.resolution}</div>}</div>;
}

function ContractDetail({ contract, onBack }: { contract: Contract; onBack: () => void }) {
  const { entities, activateContract, uploadDocuments, reprocessContract } = useContracts(); const [tab, setTab] = useState<DetailTab>(contract.source === 'NEW_DRAFT' && contract.status !== 'ACTIVE' ? 'overview' : 'overview'); const [busy, setBusy] = useState(false); const [files, setFiles] = useState<File[]>([]);
  const entity = entities.find(item => item.id === contract.primaryEntityId);
  const activate = async () => { setBusy(true); try { await activateContract(contract.id); toast.success('Contract monitoring activated.'); } catch (error) { toast.error(error instanceof Error ? error.message : 'Activation failed.'); } finally { setBusy(false); } };
  const tabs: Array<[DetailTab, string]> = [['overview', 'Overview'], ['metadata', 'Metadata'], ['clauses', `Clauses (${contract.clauses.length})`], ['review', `Review (${contract.comments?.filter(item => item.status === 'OPEN').length || 0})`], ['obligations', `Obligations (${contract.obligations.length})`], ['payments', `Payments (${contract.paymentMilestones?.length || 0})`], ['documents', `Documents (${contract.documents.length})`], ['closeout', 'Close-out'], ['approvals', 'Approvals'], ['audit', 'Audit trail']];
  return <div className="space-y-6"><div className="flex flex-wrap items-start justify-between gap-4"><div className="flex gap-3"><button onClick={onBack} className="mt-1 rounded-full p-2 text-slate-400 hover:bg-blue-50"><ArrowLeft className="h-5 w-5" /></button><div><div className="flex flex-wrap items-center gap-3"><h1 className="text-2xl font-black text-blue-950">{contract.title}</h1><Badge value={contract.status} /></div><div className="mt-1 text-sm text-slate-500">{contract.contractNumber} · {contract.contractType} · {contract.counterpartyName || 'Counterparty needs review'}</div></div></div>{(['READY_TO_ACTIVATE', 'EXECUTED', 'CLAUSE_REVIEW', 'OWNER_ASSIGNMENT'].includes(contract.status) || (contract.status === 'ACTIVE' && contract.activationGaps.length > 0)) && <button onClick={activate} disabled={busy} className="rounded-xl bg-blue-800 px-4 py-2.5 text-sm font-bold text-white disabled:opacity-50">{contract.status === 'ACTIVE' ? 'Confirm new monitoring' : 'Activate monitoring'}</button>}</div><JobProgress contractId={contract.id} />{contract.activationGaps.length > 0 && <div className="rounded-xl border border-amber-200 bg-amber-50 p-4"><div className="flex gap-3"><AlertTriangle className="mt-0.5 h-5 w-5 shrink-0 text-amber-700" /><div><div className="font-bold text-amber-900">Activation checks</div><ul className="mt-1 space-y-1 text-sm text-amber-800">{contract.activationGaps.map(gap => <li key={gap}>• {gap}</li>)}</ul></div></div></div>}<div className="flex gap-1 overflow-x-auto rounded-xl border border-slate-100 bg-white p-1">{tabs.map(([value, label]) => <button key={value} onClick={() => setTab(value)} className={`shrink-0 rounded-lg px-4 py-2 text-sm font-bold ${tab === value ? 'bg-blue-800 text-white' : 'text-slate-500 hover:bg-slate-50'}`}>{label}</button>)}</div>
    {tab === 'overview' && <div className="space-y-6">{contract.source === 'NEW_DRAFT' && contract.status !== 'ACTIVE' && <Card title="Controlled document editor" icon={FilePenLine}><DraftEditor contract={contract} /></Card>}<div className="grid gap-6 xl:grid-cols-[1.1fr_0.9fr]"><Card title="Entity and operating context" icon={Building2}><ContractMappingEditor contract={contract} /></Card><Card title="Key dates and value" icon={CircleDollarSign}><div className="grid gap-4 sm:grid-cols-2">{[['Value', `${contract.currency} ${contract.value.toLocaleString()}`], ['Effective', displayDate(contract.effectiveDate)], ['Expiry', displayDate(contract.expiryDate)], ['Notice deadline', displayDate(contract.noticeDeadline)], ['Auto-renewal', contract.autoRenewal ? 'Yes' : 'No'], ['Family', clean(contract.familyType)]].map(([label, value]) => <div key={label}><div className="text-xs text-slate-400">{label}</div><div className="mt-1 text-sm font-bold text-slate-800">{value}</div></div>)}</div><div className="mt-5 border-t pt-4"><div className="text-xs text-slate-400">Counterparty</div><div className="mt-1 font-bold text-slate-800">{contract.counterpartyName || 'Needs review'}</div><div className="mt-1 text-xs text-slate-500">{contract.counterpartyRegistrationNumber || 'Registration number not captured'}</div>{contract.vendorId && <div className="mt-2 inline-flex rounded-lg bg-emerald-50 px-2 py-1 text-xs font-bold text-emerald-700">Linked to vendor register</div>}</div></Card></div><Card title="Accountability and monitoring ownership" icon={UserRoundCheck}><OwnerEditor contract={contract} /></Card></div>}
    {tab === 'metadata' && <div className="grid gap-6 xl:grid-cols-2"><Card title="Review contract metadata" icon={FileSearch}><ContractMetadataEditor contract={contract} /></Card><Card title="Entity and operating context" icon={Building2}><ContractMappingEditor contract={contract} /></Card><div className="xl:col-span-2"><Card title="Accountability and monitoring ownership" icon={UserRoundCheck}><OwnerEditor contract={contract} /></Card></div></div>}
    {tab === 'clauses' && <div className="space-y-6">{contract.reviewIssues.length > 0 && <Card title="Playbook review queue" icon={ShieldCheck}><div className="space-y-3">{contract.reviewIssues.map(issue => <ReviewIssueCard key={issue.id} contract={contract} issue={issue} />)}</div></Card>}<Card title="Clause intelligence and human confirmation" icon={FileSearch}><div className="space-y-3">{contract.clauses.map(clause => <ClauseCard key={clause.id} contract={contract} clause={clause} />)}{!contract.clauses.length && <div className="rounded-xl border border-dashed p-10 text-center text-sm text-slate-500">No clauses extracted yet.</div>}<ManualClauseForm contract={contract} /></div></Card></div>}
    {tab === 'obligations' && <Card title="Entity-mapped obligations and dependency chains" icon={ClipboardCheck}><div className="space-y-3">{contract.obligations.map(obligation => <ObligationChainCard key={obligation.id} contract={contract} obligation={obligation} />)}<NewObligationForm contract={contract} /></div></Card>}
    {tab === 'review' && <ContractReviewWorkspace contract={contract} />}
    {tab === 'payments' && <Card title="Contractual payment schedule" icon={CircleDollarSign}><ContractPayments contract={contract} /></Card>}
    {tab === 'documents' && <Card title="Smart file repository" icon={FileCheck2}><SmartDocumentRepository contract={contract} /></Card>}
    {tab === 'closeout' && <Card title="Termination and close-out review" icon={ShieldCheck}><ContractCloseout contract={contract} /></Card>}
    {tab === 'approvals' && <Card title="Approval and execution history" icon={UserRoundCheck}><div className="space-y-3">{contract.approvals.map(item => <div key={item.id} className="flex items-start gap-3 rounded-xl border border-slate-100 p-4"><CheckCircle2 className="mt-0.5 h-5 w-5 text-blue-700" /><div className="flex-1"><div className="flex justify-between gap-2"><div className="font-bold">{item.stage} · {item.actor}</div><Badge value={item.decision} /></div><div className="mt-1 text-sm text-slate-500">Role: {item.role} · {new Date(item.createdAt).toLocaleString()}</div>{item.notes && <div className="mt-2 text-sm text-slate-700">{item.notes}</div>}</div></div>)}{!contract.approvals.length && <div className="rounded-xl border border-dashed p-8 text-center text-sm text-slate-500">No approval events recorded.</div>}</div></Card>}
    {tab === 'audit' && <Card title="Immutable activity history" icon={GitBranch}><div className="space-y-4">{contract.auditTrail.map(item => <div key={item.id} className="flex gap-3"><div className="mt-1 h-2.5 w-2.5 shrink-0 rounded-full bg-blue-600" /><div><div className="text-sm font-bold text-slate-800">{clean(item.type)}</div><div className="mt-1 text-sm text-slate-600">{item.summary}</div><div className="mt-1 text-xs text-slate-400">{item.actor} · {new Date(item.createdAt).toLocaleString()}</div></div></div>)}</div></Card>}
  </div>;
}

export function Contracts() {
  const { contracts, entities, dashboard, isLoading } = useContracts();
  const location = useLocation();
  const [params, setParams] = useSearchParams();
  const requested = params.get('view');
  const view: View = ['dashboard', 'register', 'smart-files', 'drafting', 'monitoring', 'structure', 'configuration'].includes(requested || '') ? requested as View : 'workflow';
  const setView = (next: View) => { setParams(next === 'workflow' ? {} : { view: next }); setSelectedId(undefined); };
  const [selectedId, setSelectedId] = useState<string>();
  useEffect(() => setSelectedId(params.get('record') || undefined), [location.key]);
  const selected = contracts.find(item => item.id === selectedId);
  const openContract = (id: string) => setSelectedId(id);
  useEffect(() => { document.querySelector('main')?.scrollTo({ top: 0, behavior: 'smooth' }); }, [selectedId, view]);
  if (isLoading) return <div className="flex min-h-screen items-center justify-center"><Loader2 className="h-8 w-8 animate-spin text-blue-700" /></div>;
  if (selected) return <div className="mx-auto max-w-[1600px] p-5 md:p-8"><ContractDetail contract={selected} onBack={() => setSelectedId(undefined)} /></div>;
  return <div className="mx-auto max-w-[1600px] p-5 md:p-8">
    <div className="mb-6 flex flex-wrap items-start justify-between gap-4"><div><div className="text-xs font-black uppercase tracking-[0.2em] text-red-600">Contract workflow</div><h1 className="mt-2 text-3xl font-black tracking-tight text-blue-950">{view === 'workflow' ? 'Start or continue contract work' : ({ dashboard: 'Contract Overview', register: 'Contract Register', 'smart-files': 'Smart Files', drafting: 'Drafting', monitoring: 'Monitoring', structure: 'Corporate Structure', configuration: 'Rules & Templates' } as Record<Exclude<View, 'workflow'>, string>)[view]}</h1><p className="mt-2 max-w-3xl text-sm leading-6 text-slate-500">The sidebar holds registers and configuration. This workspace stays focused on the selected contract task.</p></div><div className="flex flex-wrap gap-2"><button onClick={() => setView('smart-files')} className="flex items-center gap-2 rounded-xl border border-blue-200 bg-white px-4 py-2.5 text-sm font-bold text-blue-800"><Upload className="h-4 w-4" />Upload signed</button><button onClick={() => setView('drafting')} className="flex items-center gap-2 rounded-xl bg-blue-800 px-4 py-2.5 text-sm font-bold text-white"><Plus className="h-4 w-4" />New contract</button></div></div>
    {view === 'workflow' && <div className="grid gap-5 lg:grid-cols-3">{([
      { title: '1. Bring in a signed agreement', description: 'Upload a contract and supporting files for entity matching, clause extraction and review.', icon: Upload, action: 'Upload signed files', next: 'smart-files' },
      { title: '2. Create a controlled draft', description: 'Start from an approved template, then route changes through legal review and approval.', icon: FilePenLine, action: 'Start drafting', next: 'drafting' },
      { title: '3. Monitor commitments', description: `${dashboard?.obligationsDueSoon || 0} due soon · ${dashboard?.overdueObligations || 0} overdue. Review owners, renewals and successor obligations.`, icon: BellRing, action: 'Open monitoring', next: 'monitoring' },
    ] as const).map(item => <section key={item.title} className="flex flex-col rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><item.icon className="h-7 w-7 text-blue-700" /><h2 className="mt-5 text-lg font-bold text-blue-950">{item.title}</h2><p className="mt-2 flex-1 text-sm leading-6 text-slate-600">{item.description}</p><button onClick={() => setView(item.next)} className="mt-6 rounded-xl bg-blue-50 px-4 py-2.5 text-left text-sm font-bold text-blue-800 hover:bg-blue-100">{item.action} →</button></section>)}</div>}
    {view === 'register' && <ContractKnowledgeSearch openContract={openContract} />}
    {view === 'structure' && <CorporateStructureChart entities={entities} />}
    {view === 'dashboard' && <Dashboard openContract={openContract} changeView={setView} />}{view === 'register' && <Register openContract={openContract} />}{view === 'smart-files' && <SmartFiles openContract={openContract} />}{view === 'drafting' && <Drafting openContract={openContract} />}{view === 'monitoring' && <Monitoring openContract={openContract} />}{view === 'structure' && <Structure />}{view === 'configuration' && <><Configuration /><TemplateManager /></>}
  </div>;
}
